<script>
document.querySelectorAll('.mc-tab').forEach(function(tab){tab.addEventListener('click',function(){document.querySelectorAll('.mc-tab').forEach(t=>t.classList.remove('active'));document.querySelectorAll('.mc-panel').forEach(p=>p.classList.remove('active'));tab.classList.add('active');document.getElementById('panel-'+tab.dataset.panel).classList.add('active');});});
function toggleMigrationDrawer(){var drawer=document.getElementById('migrationDrawer');if(window.innerWidth<=900){drawer.classList.toggle('open');return;}drawer.scrollIntoView({behavior:'smooth',block:'start'});var firstField=drawer.querySelector('select,input,textarea');if(firstField){window.setTimeout(function(){firstField.focus({preventScroll:true});},450);}}
</script>
